// Connection state for the header badge. Nothing is wired to the API yet, so the
// honest default is 'demo'. Pass 'connected' / 'down' once /api/health exists.
const LABELS = {
  connected: ['Live', 'Connected to the API'],
  down: ['Disconnected', 'The API is not responding'],
  demo: ['Sample data', 'Not connected to the API'],
};

export function renderBadge(state = 'demo') {
  const [label, detail] = LABELS[state];
  return `<p class="conn" data-status="${state}" role="status">
    <span class="mark" aria-hidden="true"></span>
    <span class="conn-label">${label}</span>
    <span class="conn-detail">${detail}</span>
  </p>`;
}

