import { renderBadge } from './components/StatusBadge.js';

// Sample runs. Nothing behind it yet; the badge says so on screen.
const RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];

const STATUS = { passed: 'Passed', failed: 'Failed', running: 'Running', queued: 'Queued' };
const COLS = 6;

// Values will come from the API later, so never trust them as HTML.
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

function row(r) {
  return `<tr data-status="${esc(r.status)}">
    <th scope="row" class="id">${esc(r.id)}</th>
    <td>${esc(r.service)}</td>
    <td><span class="status" data-status="${esc(r.status)}"><span class="mark" aria-hidden="true"></span>${esc(STATUS[r.status] ?? r.status)}</span></td>
    <td class="num">${esc(r.started)}</td>
    <td class="num">${esc(r.duration)}</td>
    <td class="act"><button type="button" class="btn retry" data-run="${esc(r.id)}" aria-label="Retry run ${esc(r.id)}">Retry</button></td>
  </tr>`;
}

// One message row for loading / empty / error, so the table keeps its shape.
function message(status, title, body, action = '') {
  return `<tr class="msg"><td colspan="${COLS}">
    <span class="status" data-status="${status}"><span class="mark" aria-hidden="true"></span>${title}</span>
    <p>${body}</p>${action}
  </td></tr>`;
}

function skeleton() {
  const cell = '<td><span class="bone"></span></td>';
  return `<tr class="skel" aria-hidden="true">${cell.repeat(COLS)}</tr>`.repeat(4);
}

function summary(runs) {
  const failed = runs.filter((r) => r.status === 'failed').length;
  const scope = runs.length === 1 ? 'the last run' : `the last ${runs.length} runs`;
  return failed ? `${failed} failed in ${scope}` : `All passed in ${scope}`;
}

// ponytail: renders every row; paginate + sticky header once runs exceed ~100.
export function render(state = new URLSearchParams(location.search).get('state')) {
  const runs = state === 'empty' ? [] : RUNS;
  const body = {
    loading: skeleton(),
    error: message('failed', 'Runs could not be loaded', 'The API did not respond. Your runs are unaffected.',
      '<button type="button" class="btn" id="reload">Try again</button>'),
    empty: message('queued', 'No runs yet', 'Runs appear here as soon as one starts. Use New run to start one.'),
  }[state] ?? runs.map(row).join('');
  const head = { loading: 'Loading runs', error: 'Runs unavailable' }[state]
    ?? (runs.length ? summary(runs) : 'No runs yet');

  document.querySelector('#app').innerHTML = `
    <header class="bar">
      <span class="wordmark">pulse</span>
      ${renderBadge(state === 'error' ? 'down' : 'demo')}
      <button type="button" class="btn primary" id="new-run">New run</button>
    </header>
    <main>
      <h1>Deploy runs</h1>
      <p class="summary" data-failed="${runs.some((r) => r.status === 'failed') && !state}">${head}</p>
      <p class="notice" id="notice" role="status" aria-live="polite"></p>
      <div class="table-wrap" tabindex="0" role="region" aria-label="Deploy runs">
        <table aria-busy="${state === 'loading'}">
          <thead><tr>
            <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
            <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
            <th scope="col" class="act"><span class="sr-only">Actions</span></th>
          </tr></thead>
          <tbody>${body}</tbody>
        </table>
      </div>
    </main>`;

  // Not wired to the API yet (separate ticket). Say so instead of failing silently.
  const notice = document.querySelector('#notice');
  document.querySelectorAll('.retry').forEach((b) => b.addEventListener('click', () => {
    notice.textContent = `Retry is not connected yet, so ${b.dataset.run} was not restarted.`;
  }));
  document.querySelector('#new-run').addEventListener('click', () => {
    notice.textContent = 'New run is not connected yet, so nothing was started.';
  });
  document.querySelector('#reload')?.addEventListener('click', () => render());
}

render();

