/* pulse. Tokens: neutrals tinted to hue 250, one accent for the primary action and focus.
   Status colours only ever colour the mark; the word beside it stays ink. */
:root {
  --bg:      oklch(0.985 0.004 250);
  --surface: oklch(1 0 0);
  --ink:     oklch(0.24 0.015 250);
  --muted:   oklch(0.47 0.015 250);
  --line:    oklch(0.92 0.006 250);
  --edge:    oklch(0.62 0.015 250);
  --accent:  oklch(0.50 0.16 255);
  --on-accent: oklch(1 0 0);
  --ring:    oklch(0.50 0.16 255);
  --hover:   oklch(0.965 0.006 250);
  --ok:      oklch(0.52 0.13 150);
  --bad:     oklch(0.53 0.19 25);
  --bad-bg:  oklch(0.975 0.015 25);
  --warn:    oklch(0.55 0.11 70);
