cat > /tmp/contrast.mjs <<'EOF'
const f=(n)=>n<=0.0031308?12.92*n:1.055*Math.pow(n,1/2.4)-0.055;
const rgb=([L,C,H])=>{const h=H*Math.PI/180,a=C*Math.cos(h),b=C*Math.sin(h);
  const l=(L+0.3963377774*a+0.2158037573*b)**3, m=(L-0.1055613458*a-0.0638541728*b)**3,
        s=(L-0.0894841775*a-1.2914855480*b)**3;
  return [4.0767416621*l-3.3077115913*m+0.2309699292*s,-1.2684380046*l+2.6097574011*m-0.3413193965*s,
          -0.0041960863*l-0.7034186147*m+1.7076147010*s].map(v=>Math.round(Math.min(1,Math.max(0,f(v)))*255));};
